## Kullanım

`PrimeOneTable` bileşenini kullanmak için aşağıdaki adımları takip edebilirsiniz:

### Şablon

```html
<lib-prime-one-table
    [tableOptions]="tableOptions()"
    (onLazyLoad)="onLazyLoad($event)"
    (selectionChange)="selectionChange($event)"
>
```

### Kod Örneği
Aşağıdaki örnek, PrimeOneTable bileşenini nasıl yapılandırabileceğinizi gösterir:

```js
import { Component, inject } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { PrimeOneTableComponent } from 'prime-one-table';
import { PrimeOneTableOptions, PrimeOneColumn } from 'path-to-prime-one-table/types/types';

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [PrimeOneTableComponent, HttpClient],
  templateUrl: './app.component.html'
})
export class AppComponent {
  httpClient = inject(HttpClient);
  tableOptions = signal>({
    lazy: true,
    data: [],
    selectable: true,
    dataKey: 'id',
    sortMode: 'multiple',
    resizable: true,
    gridlines: true,
    reorderable: true,
    filter: false,
    pagination: {
        initialRows: 10,
        totalRecords: 0,
        pagination: true,
        paginationPerPageOptions: [10, 20, 50]
    },
    columns: [
        { header: 'ID', field: 'id' },
        { header: 'Başlık', field: 'title' },
        { header: 'Gövde', field: 'body' }
    ],
  });

  ngOnInit() {
    this.httpClient
      .get('https://jsonplaceholder.typicode.com/posts')
      .subscribe((res: any) => {
        this.tableOptions.update(v => ({
            ...v,
            data: res,
            pagination: {
                ...v.pagination!,
                totalRecords: res.length
            }
        }))
      });
  }

  onLazyLoad(event: TableLazyLoadEvent) {
    console.log('Lazy Load Event:', event);
    this.httpClient
      .get('https://jsonplaceholder.typicode.com/posts', {params: {_start: (event.first ?? 0) / (event.rows ?? 1), _limit: (event.rows ?? this.tableOptions().pagination?.initialRows ?? 10)}})
      .subscribe((res: any) => {
        this.tableOptions.update(v => ({
            ...v,
            data: res,
            pagination: {
                ...v.pagination!,
                totalRecords: res.length
            }
        }))
      });
  }

  selectionChange(event: any) {
    console.log('Selection Change Event:', event);
  }
}

```

