+let REQUEST_TIMEOUT = 120000;
+let isAlpineOrMusl = () => {
+  try {
+    if (execFileSync("ldd", ["--version"], {
+      stdio: ["ignore", "pipe", "pipe"]
+    }).toString().includes("musl")) {
+      return true;
+    }
+  } catch {}
