+  "linux-x64": () => isAlpineOrMusl() ? "bun-linux-x64-musl-baseline" : "bun-linux-x64-baseline",
+  "darwin-arm64": () => "bun-darwin-aarch64",
+  "darwin-x64": () => "bun-darwin-x64",
+  "win32-arm64": () => "bun-windows-aarch64",
+  "win32-x64": () => "bun-windows-x64-baseline"
+};
