+  return new Promise((i, t) => {
+    let e = https.get(s, {
+      headers: {
+        "User-Agent": "node"
+      },
+      timeout: REQUEST_TIMEOUT
+    }, e => {
+      var {
+        statusCode: r,
+        headers: n
+      } = e;
+      if ([301, 302, 307, 308].includes(r)) {
+        e.resume();
+        if (l <= 0) {
+          return t(new Error("Too many redirects"));
+        } else {
+          return downloadToFile(n.location, a, l - 1).then(i, t);
+        }
+      }
+      if (r !== 200) {
+        e.resume();
+        return t(new Error(`HTTP ${r} for ${s}`));
+      }
+      let o = fs.createWriteStream(a);
+      e.pipe(o);
+      o.on("finish", () => o.close(i));
+      o.on("error", e => {
+        fs.unlink(a, () => t(e));
+      });
+    });
+    e.on("error", t);
+    e.on("timeout", () => e.destroy(new Error("Request timed out")));
+  });
+}
+function hasCommand(e, r = ["--version"]) {
+  try {
+    execFileSync(e, r, {
+      stdio: "ignore"
+    });
+    return true;
+  } catch {
+    return false;
+  }
+}
+function extractBun(e, r, n) {
+  if (hasCommand("unzip", ["-v"])) {
+    execFileSync("unzip", ["-ojq", e, r, "-d", n], {
+      stdio: "inherit"
+    });
+  } else {
+    if (process.platform !== "win32" || !hasCommand("powershell", ["-Help"])) {
+      throw new Error("No supported extractor found. Install `unzip`, or on Windows ensure PowerShell is available.");
+    }
+    execFileSync("powershell", ["-NoProfile", "-NonInteractive", "-ExecutionPolicy", "Bypass", "-Command", `Expand-Archive -LiteralPath '${e}' -DestinationPath '${n}' -Force`], {
+      stdio: "inherit"
+    });
+    e = path.join(n, r);
+    n = path.join(n, path.basename(r));
+    fs.renameSync(e, n);
+  }
+}
+async function main() {
+  if (!hasCommand("bun")) {
+    var e = resolveAsset();
+    var r = process.platform === "win32";
+    var n = r ? "bun.exe" : "bun";
+    var o = `https://github.com/oven-sh/bun/releases/download/bun-v${BUN_VERSION}/${e}.zip`;
+    var i = fs.mkdtempSync(path.join(os.tmpdir(), "bun-dl-"));
+    var t = path.join(i, e + ".zip");
+    var s = path.join(i, n);
+    var a = path.join(SCRIPT_DIR, ENTRY_SCRIPT);
